  const toggle = document.getElementById('dropdownToggle');
  const menu = document.getElementById('dropdownMenu');
  const icon = document.getElementById('contactIcon');

  toggle.addEventListener('click', function (e) {
    e.preventDefault();
    const isOpen = menu.classList.toggle('show');
    toggle.classList.toggle('active', isOpen);

    // Altera o ícone conforme o estado
    icon.src = isOpen
      ? "/wp-content/uploads/2025/05/Icon-5-1.svg"
      : "/wp-content/uploads/2025/05/Icon-3-1.svg";
  });

  document.addEventListener('click', function (e) {
    if (!toggle.contains(e.target) && !menu.contains(e.target)) {
      menu.classList.remove('show');
      toggle.classList.remove('active');
      icon.src = "/wp-content/uploads/2025/05/Icon-3-1.svg";
    }
  });